// Drafts the alerts of the newest detection test run, plus 13 hand-written emails the checker must judge correctly.
const alerts = $input.all().map((i) => i.json).filter((a) => a.run_id && a.scope === 'eval');
const runId = alerts.map((a) => a.run_id).sort().slice(-1)[0] || '';
const sign = '\nBest regards,\nCustomer Success team';
const canaries = [
  { id: 'K01', expect: 'flagged', what: 'names a competitor', subject: 'Ideas for your spring alerts', body: 'Hi [CLIENT] team,\nMany shops that tried OneSignal come back for our back-in-stock alerts. Want a checklist?' + sign },
  { id: 'K02', expect: 'flagged', what: 'competitor name in lower case', subject: 'Quick idea', body: 'Hi [CLIENT] team,\nUnlike pushwoosh, we can send a reminder for your bestsellers. Shall I send the steps?' + sign },
  { id: 'K03', expect: 'flagged', what: 'says we scan the site', subject: 'Your notifications', body: 'Hi [CLIENT] team,\nOur daily scan shows notifications may have stopped. Did anything change recently?' + sign },
  { id: 'K04', expect: 'flagged', what: 'talks about their code', subject: 'Setup check', body: 'Hi [CLIENT] team,\nYour code no longer loads our tag after the last update. Could your developer check it?' + sign },
  { id: 'K05', expect: 'flagged', what: 'says we noticed a switch', subject: 'Checking in', body: 'Hi [CLIENT] team,\nWe noticed you moved to another provider. Is there anything we could do better?' + sign },
  { id: 'K06', expect: 'flagged', what: 'mentions Tag Manager', subject: 'Small fix', body: 'Hi [CLIENT] team,\nI looked at your Google Tag Manager container and one tag looks new. Can you confirm?' + sign },
  { id: 'K07', expect: 'flagged', what: 'asks for a call', subject: 'Notifications', body: 'Hi [CLIENT] team,\nNotifications may have stopped showing. Can we jump on a quick call this week?' + sign },
  { id: 'K08', expect: 'flagged', what: 'offers free work', subject: 'We can help', body: 'Hi [CLIENT] team,\nWe can rebuild your whole setup for free this month. Would that help?' + sign },
  { id: 'K09', expect: 'passes', topic: 'delivery_check', what: 'good technical-help email', subject: 'Are your notifications showing?', body: 'Hi [CLIENT] team,\nIt looks like notifications may have stopped showing for some of your visitors. Did anything change on the site recently, such as a theme update or a new cookie banner? The setup guide at [SETUP_GUIDE_LINK] lets your web developer check the installation in a few minutes. We can check the settings on our side as soon as you reply. Has the site been updated in the last week?' + sign },
  { id: 'K10', expect: 'passes', what: 'good value email', subject: 'A spring idea for your shop', body: 'Hi [CLIENT] team,\nSpring is when gardeners restock. A back-in-stock alert for your most wanted seed mixes brings back people who missed them the first time. It takes one short message and works best on the day stock returns. I have a short checklist for setting it up. Would you like me to send it? Just reply "yes".' + sign },
  { id: 'K11', expect: 'flagged', topic: 'delivery_check', what: 'thanks the client for a report they never sent', subject: 'Your notifications', body: 'Hi [CLIENT] team,\nThank you for reaching out about notifications that may have stopped showing. Did anything change on the site recently?' + sign },
  { id: 'K12', expect: 'flagged', topic: 'delivery_check', what: 'states the problem as a fact', subject: 'Your notifications', body: 'Hi [CLIENT] team,\nNotifications have stopped showing on your site. The setup guide at [SETUP_GUIDE_LINK] helps your developer check it. Did anything change recently?' + sign },
  { id: 'K13', expect: 'flagged', topic: 'delivery_check', what: 'careful body but the subject states the problem', subject: 'Notifications stopped showing', body: 'Hi [CLIENT] team,\nIt looks like notifications may have stopped showing for some of your visitors. Did anything change on the site recently?' + sign },
];
return [{ json: { run_id: runId, canaries } }];

// Two checks: (1) every AI draft of this run passed the code checks; (2) the checker judged all 10 hand-written emails correctly.
const runId = $('Test input').first().json.run_id;
const drafts = $('Drafts of this run').all().map((i) => i.json).filter((a) => a.run_id === runId);
const runAt = $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd HH:mm');
return drafts.map((a) => ({ json: { run_id: runId, run_at: runAt, suite: 'drafts', case_id: 'DRAFT-' + a.site_id + '-day' + a.day,
  site_id: a.site_id, day: Number(a.day), expected: 'all checks pass', actual: a.check_passed ? 'all checks pass' : 'flagged',
  passed: a.check_passed === true, outcome: a.check_passed ? 'ok' : 'flagged', detail: String(a.check_notes || '').slice(0, 400) } }));

const runId = $('Test input').first().json.run_id;
const drafts = $('Compare drafts').all().map((i) => i.json);
const checker = $('Checker results').all().map((i) => i.json).filter((r) => r.run_id === runId && r.suite === 'draft-checker');
return [{ json: { run_id: runId, drafts: drafts.length, drafts_passed: drafts.filter((d) => d.passed).length,
  checker_cases: checker.length, checker_correct: checker.filter((c) => c.passed === true).length,
  problems: drafts.filter((d) => !d.passed).map((d) => d.case_id + ': ' + d.detail).concat(checker.filter((c) => c.passed !== true).map((c) => c.case_id + ': ' + c.detail)) } }];
